  B.tpl(PF, (r) => { const p = ri(r, 2, 20) * 100, rate = T.pick(r, [2, 3, 4, 5, 6, 8]), t = ri(r, 2, 6); const i = p * rate * t / 100; return [`How much simple interest is earned on $${f(p)} at ${rate}% per year for ${t} years?`, near(r, i, [-p / 10, p / 10, -rate * 10, rate * 10, p].map((x) => Math.round(x)), (x) => "$" + f(x)), 0, `I = P × r × t = ${p} × ${rate / 100} × ${t} = $${f(i)}.`]; }, 14);
  B.tpl(PF, (r) => { const p = ri(r, 2, 20) * 100, rate = T.pick(r, [2, 4, 5, 10]); const a = p * (1 + rate / 100) * (1 + rate / 100); const aa = Math.round(a * 100) / 100; return [`You deposit $${f(p)} at ${rate}% compound interest, compounded annually. About how much will you have after 2 years?`, near(r, aa, [-p * rate / 100 * 2 + 0 - (aa - aa), p * rate / 100 * 0.5, -p * rate / 100, p * rate / 100].map((x) => Math.round(x * 100) / 100), (x) => "$" + f(Math.round(x * 100) / 100)), 0, `Year 1: $${f(Math.round(p * (1 + rate / 100) * 100) / 100)}; year 2: × ${1 + rate / 100} = $${f(aa)}.`]; }, 10);
  B.tpl(PF, (r) => { const inc = ri(r, 20, 80) * 100, rent = Math.round(inc * 0.3), food = Math.round(inc * 0.15), other = Math.round(inc * 0.2); const left = inc - rent - food - other; return [`Monthly income is $${f(inc)}. Rent is $${f(rent)}, food is $${f(food)}, and other bills are $${f(other)}. How much is left to save?`, near(r, left, [-100, 100, -50, 50, rent].map((x) => x), (x) => "$" + f(x)), 0, `${inc} − ${rent} − ${food} − ${other} = ${left}.`]; }, 10);
